  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","count","hold","morph","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  count: 2000,
  hold: 22,
  morph: 30,
  accent: "#3B5BFD",
  fontFamily: "Manrope",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type DotFieldMorphElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof DotFieldMorphBase>;

const DotFieldMorphInner = forwardRef<
  HTMLDivElement,
  DotFieldMorphElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<DotFieldMorph>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <DotFieldMorphBase
          {...(componentProps as unknown as ComponentProps<typeof DotFieldMorphBase>)}
        />
      </div>
    </Sequence>
  );
});

export const DotFieldMorph = Interactive.withSchema({
  Component: DotFieldMorphInner,
  componentName: "<DotFieldMorph>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
